"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { getListing, type Listing } from "@/lib/api";
import Navbar from "@/components/Navbar";

export default function ListingDetailPage() {
  const params = useParams();
  const router = useRouter();

  const [listing, setListing] = useState<Listing | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");
  const [guests, setGuests] = useState(2);

  const listingId = Number(params.id);

  useEffect(() => {
    async function loadListing() {
      if (!listingId || Number.isNaN(listingId)) {
        setError("Invalid listing");
        setLoading(false);
        return;
      }

      try {
        const data = await getListing(listingId);
        setListing(data);
      } catch (err) {
        console.error("Listing error:", err);
        setError("This property could not be found.");
      } finally {
        setLoading(false);
      }
    }

    loadListing();
  }, [listingId]);

  if (loading) {
    return (
      <main className="listing-detail-page">
        <Navbar />

        <div className="listing-detail-loading">
          <div className="loading-spinner" />
          <p>Loading home...</p>
        </div>
      </main>
    );
  }

  if (!listing) {
    return (
      <main className="listing-detail-page">
        <Navbar />

        <div className="listing-detail-error">
          <div className="no-results-icon">🏠</div>

          <h1>Property not found</h1>

          <p>
            {error || "We couldn't find this property."}
          </p>

          <button onClick={() => router.push("/")}>
            Back to homes
          </button>
        </div>
      </main>
    );
  }

  const images = listing.images || [];

  const nights =
    checkIn && checkOut
      ? Math.max(
          0,
          Math.ceil(
            (new Date(checkOut).getTime() -
              new Date(checkIn).getTime()) /
              (1000 * 60 * 60 * 24)
          )
        )
      : 0;

  const subtotal =
    listing.price_per_night * nights;

  const cleaningFee = nights > 0 ? 500 : 0;

  const serviceFee = subtotal * 0.12;

  const total =
    subtotal + cleaningFee + serviceFee;

  const today = new Date()
    .toISOString()
    .split("T")[0];

  function handleReserve() {
    if (!checkIn) {
      alert("Please select check-in date.");
      return;
    }

    if (!checkOut) {
      alert("Please select check-out date.");
      return;
    }

    if (nights <= 0) {
      alert("Check-out must be after check-in.");
      return;
    }

    router.push(
      `/checkout?listingId=${listing.id}&checkIn=${checkIn}&checkOut=${checkOut}&guests=${guests}`
    );
  }

  return (
    <main className="listing-detail-page">

      <Navbar />

      <div className="listing-detail-container">

        {/* ================= HEADER ================= */}

        <div className="listing-detail-header">

          <div>
            <button
              className="back-button"
              onClick={() => router.back()}
            >
              ← Back
            </button>

            <h1>{listing.title}</h1>
          </div>

          <div className="detail-actions">
            <button>↗ Share</button>
            <button>♡ Save</button>
          </div>

        </div>

        {/* ================= PHOTO GALLERY ================= */}

        <section className="detail-photo-grid">

          <div className="detail-main-photo">
            {images[0] && (
              <img
                src={images[0].image_url}
                alt={listing.title}
              />
            )}
          </div>

          <div className="detail-side-photos">

            {images.slice(1, 5).map((image) => (
              <div
                className="detail-side-photo"
                key={image.id}
              >
                <img
                  src={image.image_url}
                  alt={listing.title}
                />
              </div>
            ))}

          </div>

        </section>

        {/* ================= CONTENT ================= */}

        <div className="detail-content-layout">

          {/* ================= LEFT ================= */}

          <div className="detail-main-content">

            {/* INTRO */}

            <section className="detail-intro">

              <h2>
                Entire{" "}
                {listing.property_type.toLowerCase()}{" "}
                in {listing.location}
              </h2>

              <p className="detail-meta">
                2 guests · 1 bedroom · 1 bed · 1 bathroom
              </p>

              <p className="detail-rating">
                ★ {listing.rating.toFixed(2)}

                {listing.review_count > 0 && (
                  <>
                    {" · "}
                    {listing.review_count} reviews
                  </>
                )}
              </p>

            </section>

            {/* HOST */}

            <section className="detail-host">

              <div className="host-avatar">
                {listing.host.name
                  .charAt(0)
                  .toUpperCase()}
              </div>

              <div>
                <strong>
                  Hosted by {listing.host.name}
                </strong>

                <span>
                  {listing.host.role === "host"
                    ? "Superhost"
                    : "Experienced host"}
                </span>
              </div>

            </section>

            {/* DESCRIPTION */}

            <section className="detail-section">

              <h2>About this place</h2>

              <p>
                {listing.description}
              </p>

            </section>

            {/* AMENITIES */}

            <section className="detail-section">

              <h2>
                What this place offers
              </h2>

              <div className="amenities-grid">

                {listing.amenities
                  .slice(0, 10)
                  .map((item) => (
                    <div
                      className="amenity-item"
                      key={item.id}
                    >
                      <span>✓</span>

                      <span>
                        {item.amenity.name}
                      </span>
                    </div>
                  ))}

              </div>

              <button className="show-amenities">
                Show all amenities
              </button>

            </section>

            {/* LOCATION */}

            <section className="detail-section">

              <h2>Where you'll be</h2>

              <div className="detail-location-box">

                <div className="detail-location-icon">
                  📍
                </div>

                <div>
                  <strong>
                    {listing.location}
                  </strong>

                  <p>India</p>
                </div>

              </div>

              <div className="detail-mini-map">

                <div className="fake-map-grid">
                  <span>📍</span>

                  <strong>
                    {listing.location}
                  </strong>
                </div>

              </div>

            </section>

            {/* REVIEWS */}

            <section className="detail-section">

              <h2>
                ★ {listing.rating.toFixed(2)}
                {" · "}
                {listing.review_count} reviews
              </h2>

              <div className="review-placeholder">

                <strong>
                  Guests love this place
                </strong>

                <p>
                  Reviews from guests will appear here.
                </p>

              </div>

            </section>

          </div>

          {/* ================= BOOKING CARD ================= */}

          <aside className="booking-sidebar">

            <div className="booking-card">

              {/* PRICE */}

              <div className="booking-price">

                <strong>
                  ₹
                  {listing.price_per_night.toLocaleString(
                    "en-IN"
                  )}
                </strong>

                <span> night</span>

              </div>

              <div className="booking-rating">
                ★ {listing.rating.toFixed(2)}
              </div>

              {/* DATES */}

              <div className="booking-dates">

                <div className="booking-date-field">

                  <label>
                    CHECK-IN
                  </label>

                  <input
                    type="date"
                    value={checkIn}
                    min={today}
                    onChange={(event) =>
                      setCheckIn(
                        event.target.value
                      )
                    }
                  />

                </div>

                <div className="booking-date-field">

                  <label>
                    CHECKOUT
                  </label>

                  <input
                    type="date"
                    value={checkOut}
                    min={checkIn || today}
                    onChange={(event) =>
                      setCheckOut(
                        event.target.value
                      )
                    }
                  />

                </div>

              </div>

              {/* GUESTS */}

              <div className="booking-guests">

                <label>
                  GUESTS
                </label>

                <div className="guest-selector">

                  <span>
                    {guests}{" "}
                    {guests === 1
                      ? "guest"
                      : "guests"}
                  </span>

                  <div className="guest-buttons">

                    <button
                      onClick={() =>
                        setGuests(
                          Math.max(
                            1,
                            guests - 1
                          )
                        )
                      }
                    >
                      −
                    </button>

                    <button
                      onClick={() =>
                        setGuests(
                          guests + 1
                        )
                      }
                    >
                      +
                    </button>

                  </div>

                </div>

              </div>

              {/* PRICE BREAKDOWN */}

              {nights > 0 && (
                <div className="price-breakdown">

                  <div>
                    <span>
                      ₹
                      {listing.price_per_night.toLocaleString(
                        "en-IN"
                      )}{" "}
                      × {nights} nights
                    </span>

                    <span>
                      ₹
                      {subtotal.toLocaleString(
                        "en-IN"
                      )}
                    </span>
                  </div>

                  <div>
                    <span>
                      Cleaning fee
                    </span>

                    <span>
                      ₹
                      {cleaningFee.toLocaleString(
                        "en-IN"
                      )}
                    </span>
                  </div>

                  <div>
                    <span>
                      Service fee
                    </span>

                    <span>
                      ₹
                      {serviceFee.toLocaleString(
                        "en-IN",
                        {
                          maximumFractionDigits: 0,
                        }
                      )}
                    </span>
                  </div>

                  <hr />

                  <div className="total-row">

                    <strong>
                      Total
                    </strong>

                    <strong>
                      ₹
                      {total.toLocaleString(
                        "en-IN",
                        {
                          maximumFractionDigits: 0,
                        }
                      )}
                    </strong>

                  </div>

                </div>
              )}

              {/* RESERVE */}

              <button
                className="reserve-button"
                onClick={handleReserve}
              >
                Reserve
              </button>

              <p className="no-charge">
                You won't be charged yet
              </p>

            </div>

          </aside>

        </div>

      </div>

    </main>
  );
}